112:     while index < args.len() {
113:         let option = args[index].as_str();
114:         match option {
115:             "--width" | "--height" | "--samples" | "--output" | "--format" => {}
116:             other => return Err(format!("unknown option {other:?}")),
117:         }
118:         let value = args
119:             .get(index + 1)
120:             .ok_or_else(|| format!("{option} needs a value"))?;
121:         index += 2;
122:         match option {
123:             "--width" => width = parse_dimension(option, value)?,
124:             "--height" => height = parse_dimension(option, value)?,
125:             "--samples" => {
126:                 let count = value
