137:                     "png" => Format::Png,
138:                     "ppm" => Format::Ppm,
139:                     other => return Err(format!("--format: unrecognised format {other:?}")),
140:                 });
141:             }
142:             _ => unreachable!("only the five options reach this match"),
143:         }
144:     }
