167: /// An explicit format, or the one named by the output file's extension.
168: fn resolve_format(explicit: Option<Format>, output: &Path) -> Result<Format, String> {
169:     if let Some(format) = explicit {
170:         return Ok(format);
171:     }
172:     match output.extension().and_then(|extension| extension.to_str()) {
173:         Some("png") => Ok(Format::Png),
174:         Some("ppm") => Ok(Format::Ppm),
175:         _ => Err(format!(
